def blocks_equal(b1, b2):
    return b1 == b2

# Find which blocks are identical
identical_pairs = []
for i, j in combinations(range(len(blocks)), 2):
    k1, k2 = list(blocks.keys())[i], list(blocks.keys())[j]
    if blocks_equal(list(blocks.values())[i], list(blocks.values())[j]):
