# Another hypothesis: the output might be a specific color whose 
# pattern (connected component count, etc.) matches something

# Count connected components of each non-background color
def count_color_components(block, color):
    """Count 4-connected components of a given color"""
    rows = len(block)
    cols = len(block[0])

    visited = [[False]*cols for _ in range(rows)]
    count = 0

    for r in range(rows):
        for c in range(cols):
            if block[r][c] == color and not visited[r][c]:
                count += 1
                # BFS/DFS to mark all connected cells
                stack = [(r, c)]
                while stack:
                    cr, cc = stack.pop()
                    if visited[cr][cc]:
                        continue
                    visited[cr][cc] = True

                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if not visited[nr][nc] and block[nr][nc] == color:
                                stack.append((nr, nc))
    return count

for pos, info in sorted(block_to_output.items()):
    idx = pos[0] * 3 + pos[1]
    block = blocks[idx]['block']

    # Count components for each non-bg color
    components = {}
    for row in block:
        for cell in row:
            if cell not in components:
                components[cell] = 0
            components[cell] += count_color_components(block, cell)

    print(f"Block {pos} -> Output {info['output']}")
    print(f"  Color components: {components}")
    print()

