# Look for specific shapes within blocks - maybe the key is a shape of a certain color

def find_l_shape(block, color):
    """Find if there's an L-shape (corner) of given color"""
    rows = len(block)
    cols = len(block[0])

    for r in range(rows-1):
        for c in range(cols-1):
            # Check all 4 orientations of L-shape
            if (block[r][c] == color and block[r+1][c] == color and block[r][c+1] == color):
                return True, ('top', c, r)
            if (block[r][c] == color and block[r+1][c] == color and block[r+1][c+1] == color):
                return True, ('bottom-left', c, r)
            if (block[r][c] == color and block[r+1][c+1] == color and block[r][c+1] == color):
                return True, ('top-right', c, r)
            if (block[r][c+1] == color and block[r+1][c+1] == color and block[r+1][c] == color):
                return True, ('bottom-right', c, r)
    return False, None

for pos, info in sorted(block_to_output.items()):
    idx = pos[0] * 3 + pos[1]
    block = blocks[idx]['block']

    l_shapes = {}
    for row in block:
        for cell in row:
            if cell not in l_shapes:
                l_shapes[cell] = []
            has_l, loc = find_l_shape(block, cell)
            if has_l:
                l_shapes[cell].append(loc)

    print(f"Block {pos} -> Output {info['output']}")
    for color, locations in l_shapes.items():
        if color != 5:
            print(f"  Color {color}: {len(locations)} L-shapes")
    print()

# Let me try yet another approach: count occurrences of each color in each region
