def count_colors_in_region(data, out_r, out_c):
    """Count non-bg colors in the 3x3 region"""
    start_r, start_c = 3*out_r, 3*out_c

    counts = {}
    for r in range(3):
        for c in range(3):
            val = data[start_r+r][start_c+c]
            if val != 5:
                counts[val] = counts.get(val, 0) + 1
    return counts

